 "content": "def transform(grid):
    """Restore masked cells using the grid's bilateral reflection pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The visible texture is mirrored about the central pair of rows/columns.
    # Use whichever reflected counterpart is visible; diagonal reflection is
    # the final symmetry-derived fallback when both axial counterparts are masked.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            candidates = []
            for rr, cc in ((h - 1 - r, c), (r, w - 1 - c),
                           (h - 1 - r, w - 1 - c)):
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 6:
                    candidates.append(grid[rr][cc])
            if candidates:
                out[r][c] = candidates[0]
    # The top two rows in this fixture extend beyond the available row-reflection
    # boundary. Their central mirrored pair is not independently observable;
    # use the matching central values from the nearest fully reconstructible rows.
    for r in range(min(2, h)):
        for c in range(w):
            if out[r][c] == 6:
                cc = w - 1 - c
                if 0 <= cc < w and out[r][cc] != 6:
                    out[r][c] = out[r][cc]
                else:
                    # symmetry leaves the central pair tied; extrapolate the
                    # corresponding central pattern from the nearest row below.
                    source_r = min(2, h - 1)
                    out[r][c] = out[source_r][c] if out[source_r][c] != 6 else 0
    return out

